// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like token that records transfers
        Token token = new Token();
        address from = address(0x123);
        address to = address(0x456);
        uint amount = 100;
        // Mint tokens to from
        token.mint(from, amount);
        // Approve the C contract to transfer from from
        vm.prank(from);
        token.approve(address(c), amount);
        // Build the _tos array with one recipient
        address[] memory tos = new address[](1);
        tos[0] = to;
        // Call transfer through C
        c.transfer(from, address(token), tos, amount);
        // In the reference P, the loop runs once (i=0 < 1) and transfers tokens to to.
        // In the mutant M, the loop condition is i < 0, so it never runs, and to gets nothing.
        uint toBalance = token.balanceOf(to);
        assertTrue(toBalance == amount, "to should have received tokens");
    }
}

// Minimal ERC20 token to track balances
contract Token {
    mapping(address => uint) public balanceOf;
    mapping(address => mapping(address => uint)) public allowance;
    function mint(address to, uint amount) public {
        balanceOf[to] += amount;
    }
    function approve(address spender, uint amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    function transferFrom(address from, address to, uint amount) public returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Simple ERC20-like token to track transfers
    address token;

    function setUp() public {
        c = new C();
        // Deploy a simple token that records balances
        token = address(new SimpleToken());
        // Give from address some tokens
        SimpleToken(token).mint(address(0x123), 100);
    }

    function testRegression_property() public {
        // Create array of 3 addresses
        address[] memory tos = new address[](3);
        tos[0] = address(0xA);
        tos[1] = address(0xB);
        tos[2] = address(0xC);

        // Call transfer from 0x123 with 10 tokens each
        vm.prank(address(0x123));
        c.transfer(address(0x123), token, tos, 10);

        // After correct call: 0xA, 0xB, 0xC should each have 10 tokens
        // After buggy call: only 0xC has 10 tokens, 0xA and 0xB have 0
        // Assert that 0xA has 10 tokens (will pass on reference, fail on buggy)
        assertTrue(SimpleToken(token).balanceOf(address(0xA)) == 10);
    }
}

contract SimpleToken {
    mapping(address => uint256) public balanceOf;

    function transferFrom(address from, address to, uint256 amount) external {
        require(balanceOf[from] >= amount);
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }
}
